package com.example.bandlink.controller; import com.example.bandlink.repository.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/notifications") public class NotificationController{private final NotificationRepository notifications;private final UserRepository users;public NotificationController(NotificationRepository n,UserRepository u){notifications=n;users=u;}@GetMapping public List<com.example.bandlink.entity.Notification> list(Authentication a){return notifications.findByUserIdOrderByCreatedAtDesc(current(a));}@GetMapping("/unread-count") public Map<String,Long> unread(Authentication a){return Map.of("count",notifications.countByUserIdAndReadAtIsNull(current(a)));}private Long current(Authentication a){return users.findByEmail(a.getName()).orElseThrow().getId();}}
